@isTest
private class LSOAccessRequestTriggerHandlerTest {

    private static User createTestUser(String uniqueKey) {
        Profile p = [SELECT Id FROM Profile WHERE Name = 'Standard User' LIMIT 1];
        User u = new User(
            FirstName = 'Test',
            LastName = 'User ' + uniqueKey,
            Alias = uniqueKey.left(8),
            Email = uniqueKey + '@example.test.com',
            Username = uniqueKey + '@example.test.com.lsotest',
            EmailEncodingKey = 'UTF-8',
            LanguageLocaleKey = 'en_US',
            LocaleSidKey = 'en_US',
            TimeZoneSidKey = 'America/Chicago',
            ProfileId = p.Id
        );
        insert u;
        return u;
    }

    @isTest
    static void testSecondOpenRequestForSameUserIsBlocked() {
        User targetUser = createTestUser('req1' + System.currentTimeMillis());

        LSO_Cross_Country_Access_Request__c first = new LSO_Cross_Country_Access_Request__c(
            Requested_User__c = targetUser.Id,
            Business_Justification__c = 'Initial access need.'
        );
        insert first;

        LSO_Cross_Country_Access_Request__c second = new LSO_Cross_Country_Access_Request__c(
            Requested_User__c = targetUser.Id,
            Business_Justification__c = 'A second, concurrent request.'
        );

        Boolean blocked = false;
        try {
            insert second;
        } catch (DmlException e) {
            blocked = true;
            System.assert(e.getMessage().contains('already has an open'), 'Unexpected error: ' + e.getMessage());
        }
        System.assert(blocked, 'A second open request for the same user should have been blocked.');
    }

    @isTest
    static void testNewRequestAllowedOnceFirstIsFinal() {
        User targetUser = createTestUser('req2' + System.currentTimeMillis());

        LSO_Cross_Country_Access_Request__c first = new LSO_Cross_Country_Access_Request__c(
            Requested_User__c = targetUser.Id,
            Business_Justification__c = 'Initial access need.'
        );
        insert first;

        first.Status__c = 'Rejected';
        update first;

        LSO_Cross_Country_Access_Request__c second = new LSO_Cross_Country_Access_Request__c(
            Requested_User__c = targetUser.Id,
            Business_Justification__c = 'A follow-up request after rejection.'
        );

        Test.startTest();
        insert second;
        Test.stopTest();

        System.assertNotEquals(null, second.Id, 'A new request should be allowed once the prior one is final.');
    }
}
